        \node[gnode,text width = 2.1cm] (b) at (-3.2,-2){\autoref{lem:transduce laminar tree induced by weakly-partitive family}\phantom{blablabla}
        \scriptsize \textcolor{teal}{weakly-partitive set system $\rightarrow$ laminar tree}};

        \node[gnode,text width = 2.35cm] (c) at (3,-2){\autoref{lem:transduce laminar tree induced by weakly-bipartitive family}\phantom{blablabla}
        \scriptsize \textcolor{teal}{weakly-bipartitive set system $\rightarrow$ laminar tree}};

        \node[gnode,text width = 2.72cm] (d) at (-5.25,-4.2){\autoref{thm:transduce weakly-partitive tree}\phantom{blablabla}
        \scriptsize \textcolor{teal}{weakly-partitive set system $\rightarrow$ weakly-partitive tree}};

        \node[gnode,text width = 2.4cm] (e) at (-1.6,-4.2){\autoref{thm:transduce modular decomposition}\phantom{blablabla}
        \scriptsize \textcolor{teal}{graph $\rightarrow$ modular decomposition}};

        \node[gnode,text width = 2.97cm] (g) at (2.1,-4.2){\autoref{thm:transduce weakly-bipartitive tree}\phantom{blablabla}
        \scriptsize \textcolor{teal}{weakly-bipartitive set system $\rightarrow$ weakly-bipartitive tree}};

        \node[gnode,text width = 2.05cm] (h) at (6,-4.2){\autoref{thm:split}\phantom{blablabla}
        \scriptsize \textcolor{teal}{graph $\rightarrow$ split decomposition}};

        \node[gnode,text width = 2.4cm] (f) at (-3.2,-5.8){\autoref{thm:transduce cotree}\phantom{blablabla}
        \scriptsize \textcolor{teal}{cograph $\rightarrow$ cotree}};

        \node[gnode,text width = 3.6cm] (i) at (5.2,-5.65){\autoref{thm:bi-join1} \& \ref{thm:bi-join2}
        \scriptsize \textcolor{teal}{graph $\rightarrow$ bi-join \phantom{blabla} decomposition}};


        \draw[ns1, -Stealth] (a) -- (b);
        \draw[ns1, -Stealth] (b) -- (c);
        \draw[ns1, -Stealth] (b) -- (d);
        \draw[ns1, -Stealth] (b) -- (e);
        \draw[ns1, -Stealth] (b) -- (f);
        \draw[ns1, -Stealth] (c) -- (g);
        \draw[ns1, -Stealth] (c) -- (h);
        \draw[ns1, -Stealth] (c) -- (i);

    \end{tikzpicture}
    \caption{
        Overview of the various transductions in the paper. An arrow from $x$ to $y$ indicates that result $x$ is used in the proof of result $y$.
    }
    \label{fig:overview}
